"""Criteria for `syncthreads-must-be-uniform`.

The criterion checks “which line, which rule, and whether it was waived,” not the full message text—the message can
change, while line number and rule name are the contract.
"""

from pathlib import Path

from _checks import simt

PREAMBLE = "import pypto_pro.language as pl\n\n\n"


def _write(
    tmp_path: Path,
    body: str,
    *,
    decorator='@pl.vector_function(mode="simt")',
    docstring: str = "",
) -> Path:
    doc = f'    """{docstring}\n    """\n' if docstring else ""
    text = PREAMBLE + f"{decorator}\ndef _body(out):\n" + doc + body
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    return path


BODY = 6
"""Line number of the first function-body line in the file generated by `_write` (one import line + two blank lines +
decorator + def)."""


def _hits(path: Path) -> list[tuple[int, str, bool]]:
    return [(f.lineno, f.rule, f.waived) for f in simt.check(path)]


# ---------------------------------------------------------------------------
# Reported cases
# ---------------------------------------------------------------------------


def test_syncthreads_inside_an_if_is_reported(tmp_path):
    """The core case for this rule. The docstring prohibits it, parsing does not block it, and the symptom is a hang."""
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n"
        "    if tid > 0:\n"
        "        pl.simt.syncthreads()\n"
        "    out[0, tid] = tid\n",
    )
    assert _hits(path) == [(BODY + 2, simt.RULE, False)]


def test_syncthreads_inside_a_loop_is_reported(tmp_path):
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n"
        "    for i in pl.range(0, 4):\n"
        "        pl.simt.syncthreads()\n",
    )
    assert _hits(path) == [(BODY + 2, simt.RULE, False)]


def test_a_nested_branch_is_reported_once(tmp_path):
    """Nested branches produce one finding for the call, not one per branch level."""
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n"
        "    if tid > 0:\n"
        "        if tid < 8:\n"
        "            pl.simt.syncthreads()\n",
    )
    assert _hits(path) == [(BODY + 3, simt.RULE, False)]


def test_two_calls_are_reported_separately(tmp_path):
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n"
        "    if tid > 0:\n"
        "        pl.simt.syncthreads()\n"
        "    while tid > 100:\n"
        "        pl.simt.syncthreads()\n",
    )
    assert _hits(path) == [(BODY + 2, simt.RULE, False), (BODY + 4, simt.RULE, False)]


# ---------------------------------------------------------------------------
# Non-reported cases: these determine whether it is a useful gate or noise.
# ---------------------------------------------------------------------------


def test_syncthreads_at_the_top_level_passes(tmp_path):
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n"
        "    pl.simt.syncthreads()\n"
        "    out[0, tid] = tid\n",
    )
    assert _hits(path) == []


def test_fences_inside_a_branch_pass(tmp_path):
    """**Fences are not subject to this rule** (the docstring explicitly allows them). Banning both would reject correct
    kernels.
    """
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n"
        "    if tid > 0:\n"
        "        pl.simt.threadfence_block()\n"
        "        pl.simt.threadfence()\n",
    )
    assert _hits(path) == []


def test_a_non_simt_vector_function_is_out_of_scope(tmp_path):
    """Do not inspect `vector_function` forms outside `mode="simt"`; they do not contain `syncthreads`."""
    path = _write(
        tmp_path,
        "    if True:\n        pl.simt.syncthreads()\n",
        decorator="@pl.vector_function",
    )
    assert _hits(path) == []


def test_a_mode_from_a_variable_is_not_judged(tmp_path):
    """A variable-valued mode cannot be resolved statically. **Do not report it**; a “possible” violation would make the
    tool noisy.
    """
    path = _write(
        tmp_path,
        "    if True:\n        pl.simt.syncthreads()\n",
        decorator="@pl.vector_function(mode=MODE)",
    )
    assert _hits(path) == []


def test_a_plain_call_in_a_nested_helper_is_out_of_scope(tmp_path):
    """Nested definitions are handled in their own pass; do not attribute their calls to branches in the outer
    function.
    """
    text = (
        PREAMBLE + '@pl.vector_function(mode="simt")\ndef _body(out):\n'
        "    tid = pl.simt.linear_thread_idx()\n"
        "    if tid > 0:\n"
        "        def _inner():\n"
        "            pass\n"
        "        _inner()\n"
        "    pl.simt.syncthreads()\n"
    )
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    assert _hits(path) == []


# ---------------------------------------------------------------------------
# Counterexample declaration cases
# ---------------------------------------------------------------------------


def test_a_declared_counterexample_is_waived_but_still_printed(tmp_path):
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n"
        "    if tid > 0:\n"
        "        pl.simt.syncthreads()\n",
        docstring=f"反例：{simt.RULE} —— 这一例的内容就是这条违规本身，只解析不上板",
    )
    hits = _hits(path)
    assert hits == [(BODY + 4, simt.RULE, True)], hits


def test_a_stale_declaration_is_itself_reported(tmp_path):
    """When the declaration remains but the violation is gone, report the declaration itself. Waivers can go stale and
    hide a real future violation.
    """
    path = _write(
        tmp_path,
        "    tid = pl.simt.linear_thread_idx()\n    pl.simt.syncthreads()\n",
        docstring=f"反例：{simt.RULE} —— 声明留着但违规已经改掉了",
    )
    assert _hits(path) == [(BODY - 1, simt.RULE, False)]
